      {"text": "Список определяющих величин: r, t, κ, p_κ, Q0μ/(2πkh).", "claims": ["c1"], "hypothesis": false},
      {"text": "Размерности каждой величины.", "claims": ["c2", "c3"], "hypothesis": false}
    ],
    "manual_steps": [
      {"text": "Выписать размерности каждой величины.", "claims": ["c2", "c3"], "hypothesis": false},
      {"text": "Найти три величины с независимыми размерностями.", "claims": ["c5"], "hypothesis": false},
      {"text": "Составить безразмерные аргументы и записать P = f(...).", "claims": ["c4", "c6"], "hypothesis": false}
    ],
    "judgment_points": [
      {"text": "Какие величины включить в список определяющих. В книге список задан автором.", "claims": ["c1"], "hypothesis": true},
      {"text": "Какие три величины выбрать как независимые: r, t и p_κ.", "claims": ["c5"], "hypothesis": false}
    ],
    "time": [
      {"text": "Подбор безразмерных комбинаций без подсказки занимает время. Для сложных случаев число комбинаций растёт.", "claims": [], "hypothesis": true}
    ],
    "typical_errors": [
      {"text": "Забыть одну из величин, например вязкость или проницаемость, и потерять зависимость.", "claims": [], "hypothesis": true},
      {"text": "Считать безразмерность достаточной для ответа, не проверяя вид функции f.", "claims": [], "hypothesis": true},
      {"text": "Перепутать размерность комплекса Q0μ/(2πkh) с размерностью дебита.", "claims": ["c3"], "hypothesis": true}
    ]
  },
